import type { AudioTrack } from 'videowright';

/**
 * Rendered audio track v1 for the Sovra Verify demo.
 *
 * VO-only: one narration cue, full file, placed at 0s. Rendered from
 * audio_plan.md with ffmpeg (loudnorm to -16 LUFS integrated, true peak
 * -1.5 dB), which is the single command recorded under "Final mix command".
 * The voiceover itself was generated by ElevenLabs with the Alice voice; see
 * ../../originals/voiceovers/alice-uk-v2/audio_meta.json for the voice note.
 *
 * The perSegment advances below are generated, not hand-timed: they come from
 * `node scripts/derive-advances.mjs --write` in the project root, which places
 * each reveal on the sentence of the recorded narration that motivates it (see
 * ../../beat_map.json) and is verified by `npm run check`. Do not edit them by
 * hand; a hand-timed array is how the verdict panel in `sovra-finding` came to
 * be authored but never shown.
 */
const track: AudioTrack = {
	audio_file: './audio/tracks/v1/track.mp3',
	length_s: 115.224,
	timing: {
		perSegment: {
			'sovra-problem': [6.316, 13.653],
			'sovra-corpus': [0.5, 3.889, 8.289, 13.224],
			'sovra-run': [1.021, 7.058, 13.537],
			'sovra-finding': [0.5, 4.702, 11.018, 15.429],
			'sovra-negative': [2.276, 14.153, 21.212],
			'sovra-review-export': [5.677, 11.157],
			'sovra-results': [0.5, 6.571, 27.012],
		},
	},
	audio_plan_path: '../audio_plan.md',
	plan_snapshot_path: './plan_snapshot.md',
	created_at: '2026-10-13T02:20:00Z',
	notes:
		"VO-only. Single cue, full file, 0s. Advance times are segment-relative and derived from the ElevenLabs word alignment by scripts/derive-advances.mjs: a segment needs one entry per `waitForNext()` plus one for its span, each reveal sits at the start of the recorded sentence that motivates it, and a sentence cited by two reveals has its speaking time split between them. Two floors apply — an advance must be positive (the renderer rejects 0) and a segment's first reveal must clear its 400 ms incoming crossfade. The renderer uses the last advance of a segment as that whole segment duration, so the last value is the length of the segment narration span (the next section start minus this one, and the file length for the final segment). The seven spans sum to 117.432 s, the length of the narration file.",
};

export default track;
